from docx import Document
import re
d=Document('output/offer_letter_filled.docx')
parts=[]
def grab(p): parts.append(p.text)
for p in d.paragraphs: grab(p)
for t in d.tables:
    for row in t.rows:
        for c in row.cells:
            for p in c.paragraphs: grab(p)
            for nt in c.tables:
                for r2 in nt.rows:
                    for c2 in r2.cells:
                        for p in c2.paragraphs: grab(p)
for s in d.sections:
    for hf in [s.header,s.first_page_header,s.even_page_header,s.footer,s.first_page_footer,s.even_page_footer]:
        for p in hf.paragraphs: grab(p)
full='\n'.join(parts)
leftover=re.findall(r'\{\{[^}]*\}\}', full)
print('LEFTOVER:', leftover)
print('IF/RELOC markers:', re.findall(r'IF_RELOCATION|END_IF_RELOCATION', full))
print('RELOC content present:', 'RELOCATION' in full or '9,750' in full or '17' in full)
# show relevant lines
for line in parts:
    if 'reloc' in line.lower() or '9,750' in line or 'René' in line:
        print('>>', repr(line))
